package com.fream.back.domain.m99.service.kafka;

import com.fream.back.domain.m99.dto.Xsw86RequestDto;
import com.fream.back.domain.m99.dto.kafka.Xrb42Event;
import com.fream.back.domain.m99.entity.Xhq12;
import com.fream.back.domain.m99.entity.Xhq12Status;
import com.fream.back.domain.m99.repository.Xhq12Repository;
import com.fream.back.domain.m99.service.command.Xhq12CommandService;
import com.fream.back.domain.m64.entity.Xjt45;
import com.fream.back.domain.m64.service.command.Xjt45CommandService;
import com.fream.back.domain.m45.entity.Xfr60;
import com.fream.back.domain.m45.service.command.Xfr60CommandService;
import com.fream.back.domain.m22.entity.Xjm45;
import com.fream.back.domain.m22.service.query.Xjm45QueryService;
import com.fream.back.domain.m63.entity.Xms75;
import com.fream.back.domain.m63.service.command.Xms75CommandService;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.kafka.annotation.KafkaListener;
import org.springframework.kafka.core.KafkaTemplate;
import org.springframework.kafka.support.Acknowledgment;
import org.springframework.messaging.handler.annotation.Payload;
import org.springframework.messaging.simp.SimpMessagingTemplate;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.time.Duration;
import java.time.Instant;
import java.time.LocalDateTime;
import java.util.HashMap;
import java.util.Map;





@Service
@RequiredArgsConstructor
@Slf4j
public class Xhq12EventConsumer {

    private final Xhq12Repository orderRepository;
    private final Xjt45CommandService paymentCommandService;
    private final Xfr60CommandService orderShipmentCommandService;
    private final Xms75CommandService warehouseStorageCommandService;
    private final Xjm45QueryService userQueryService;
    private final Xhq12EventProducer orderEventProducer;
    private final SimpMessagingTemplate messagingTemplate;
    private final KafkaTemplate<String, Map<String, Object>> notificationKafkaTemplate;





    @KafkaListener(
            topics = "order-processing-topic",
            groupId = "order-processing-group",
            containerFactory = "orderProcessingKafkaListenerContainerFactory"
    )
    @Transactional
    public void handleOrderProcessingEvent(
            @Payload Xrb42Event event,
            Acknowledgment acknowledgment) {

        Instant start = Instant.now();

        try {
            log.info("주문 처리 이벤트 수신: 주문ID={}, 이벤트ID={}",
                    event.getOrderId(), event.getEventId());


            if (isOrderAlreadyProcessed(event.getOrderId())) {
                log.warn("이미 처리된 주문 요청 - 중복 처리 방지: 주문ID={}", event.getOrderId());
                acknowledgment.acknowledge();
                return;
            }


            Xhq12 order = orderRepository.findById(event.getOrderId())
                    .orElseThrow(() -> new IllegalArgumentException(
                            "주문을 찾을 수 없습니다. 주문ID: " + event.getOrderId()));

            Xjm45 user = userQueryService.findByEmail(event.getUserEmail());


            if (!order.getUser().getId().equals(user.getId())) {
                log.error("주문과 사용자 정보 불일치: 주문ID={}, 주문사용자ID={}, 요청사용자ID={}",
                        event.getOrderId(), order.getUser().getId(), user.getId());
                throw new IllegalArgumentException("주문과 사용자 정보가 일치하지 않습니다.");
            }


            processCompleteOrder(order, user, event.getRequestDto());


            sendSuccessNotification(event.getOrderId(), event.getUserEmail());


            acknowledgment.acknowledge();


            Instant end = Instant.now();
            Duration duration = Duration.between(start, end);
            log.info("주문 처리 완료 - 소요시간: {}ms, 주문ID={}", duration.toMillis(), event.getOrderId());

        } catch (Exception e) {
            log.error("주문 처리 실패: 주문ID={}, 오류={}", event.getOrderId(), e.getMessage(), e);
            handleOrderProcessingFailure(event, e, acknowledgment);
        }
    }




    @KafkaListener(
            topics = "order-retry-topic",
            groupId = "order-retry-group",
            containerFactory = "orderProcessingKafkaListenerContainerFactory"
    )
    @Transactional
    public void handleOrderRetryEvent(
            @Payload Xrb42Event event,
            Acknowledgment acknowledgment) {

        try {
            log.info("주문 재시도 처리: 주문ID={}, 재시도횟수={}",
                    event.getOrderId(), event.getRetryCount());

            if (event.isMaxRetryExceeded()) {
                log.error("최대 재시도 횟수 초과: 주문ID={}, 재시도횟수={}",
                        event.getOrderId(), event.getRetryCount());


                sendFailureNotification(event.getOrderId(), event.getUserEmail(), "최대 재시도 횟수 초과");
                acknowledgment.acknowledge();
                return;
            }


            if (isOrderAlreadyProcessed(event.getOrderId())) {
                log.info("재시도 중 주문 완료 확인: 주문ID={}", event.getOrderId());
                acknowledgment.acknowledge();
                return;
            }


            Thread.sleep(Math.min(1000 * event.getRetryCount(), 5000));


            handleOrderProcessingEvent(event, acknowledgment);

        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
            log.error("주문 재시도 중 인터럽트 발생: 주문ID={}", event.getOrderId());
            acknowledgment.acknowledge();
        } catch (Exception e) {
            log.error("주문 재시도 처리 중 오류: 주문ID={}, 오류={}",
                    event.getOrderId(), e.getMessage(), e);
            acknowledgment.acknowledge();
        }
    }




    private void processCompleteOrder(Xhq12 order, Xjm45 user, Xsw86RequestDto requestDto) {
        try {
            log.info("전체 주문 처리 시작: 주문ID={}", order.getId());


            Xjt45 payment = paymentCommandService.processPayment(order, user, requestDto.getPaymentRequest());
            order.assignPayment(payment);

            if (!payment.isSuccess()) {
                throw new RuntimeException("결제 실패: " + payment.getStatus());
            }

            log.info("결제 처리 완료: 주문ID={}, 결제ID={}", order.getId(), payment.getId());


            Xfr60 shipment = orderShipmentCommandService.createOrderShipment(
                    order,
                    requestDto.getReceiverName(),
                    requestDto.getReceiverPhone(),
                    requestDto.getPostalCode(),
                    requestDto.getAddress()
            );
            order.assignOrderShipment(shipment);
            log.info("배송 정보 생성 완료: 주문ID={}", order.getId());


            if (!order.getStatus().canTransitionTo(Xhq12Status.PAYMENT_COMPLETED)) {
                throw new RuntimeException("결제 완료 상태로 전환할 수 없습니다. 현재 상태: " + order.getStatus());
            }
            order.updateStatus(Xhq12Status.PAYMENT_COMPLETED);

            if (requestDto.isWarehouseStorage()) {

                Xms75 warehouseStorage = warehouseStorageCommandService.createOrderStorage(order, user);
                order.assignWarehouseStorage(warehouseStorage);


                if (order.getStatus().canTransitionTo(Xhq12Status.PREPARING)) {
                    order.updateStatus(Xhq12Status.PREPARING);
                }
                if (order.getStatus().canTransitionTo(Xhq12Status.IN_WAREHOUSE)) {
                    order.updateStatus(Xhq12Status.IN_WAREHOUSE);
                }
                if (order.getStatus().canTransitionTo(Xhq12Status.COMPLETED)) {
                    order.updateStatus(Xhq12Status.COMPLETED);
                }

                log.info("창고 보관 처리 완료: 주문ID={}", order.getId());
            } else {

                if (order.getStatus().canTransitionTo(Xhq12Status.PREPARING)) {
                    order.updateStatus(Xhq12Status.PREPARING);
                }
                log.info("배송 준비 완료: 주문ID={}", order.getId());
            }


            orderRepository.save(order);
            log.info("전체 주문 처리 완료: 주문ID={}, 최종상태={}", order.getId(), order.getStatus());

        } catch (Exception e) {
            log.error("전체 주문 처리 실패: 주문ID={}, 오류={}", order.getId(), e.getMessage(), e);
            throw e;
        }
    }




    private boolean isOrderAlreadyProcessed(Long orderId) {
        try {
            Xhq12 order = orderRepository.findById(orderId).orElse(null);
            if (order == null) {
                return false;
            }


            Xhq12Status currentStatus = order.getStatus();
            return currentStatus != Xhq12Status.PENDING_PAYMENT;

        } catch (Exception e) {
